mapper.select:
select total.* , ( select GROUP_CONCAT(cc.contract_id) from con_contract cc where cc.lease_channel = 'CON_CONTRACT'
and cc.project_id = #{projectId}
and cc.contract_id = #{contractId}
) contractIds from ( SELECT prj.* FROM ( SELECT pp.project_id as docId, pp.CREATION_DATE as createDate, '项目节点' as description, 'PRJ_PROJECT' as docType, 'PRJ' as classType, (SELECT ppm.process_instance_id FROM prj_project_meeting ppm WHERE ppm.project_id=pp.project_id limit 1) as processInstanceId, (SELECT scvb.MEANING FROM sys_code_value_b scvb WHERE scvb.CODE_ID=( SELECT scb.CODE_ID FROM sys_code_b scb WHERE scb.CODE='PRJ.PROJECT_STATUS' ) AND scvb.VALUE=pp.project_status) as currentStatus FROM prj_project pp WHERE
pp.project_id = #{projectId}
pp.project_id in ( SELECT cc.project_id FROM con_contract cc WHERE cc.contract_id=#{contractId} )
ORDER BY createDate ) prj UNION ALL SELECT prj_meet.* FROM ( SELECT ppm.project_meeting_id as docId, ppm.CREATION_DATE as createDate, '项目上会' as description, 'PRJ_PROJECT_MEETTING' as docType, 'PRJ' as classType, ppm.process_instance_id as processInstanceId, (SELECT scvb.MEANING FROM sys_code_value_b scvb WHERE scvb.CODE_ID=( SELECT scb.CODE_ID FROM sys_code_b scb WHERE scb.CODE='PRJ.PROJECT_STATUS' ) AND scvb.VALUE=ppm.meeting_status) as currentStatus FROM prj_project_meeting ppm WHERE
ppm.project_id = #{projectId}
ppm.project_id = ( SELECT cc.project_id FROM con_contract cc WHERE cc.contract_id=#{contractId} )
ORDER BY createDate ) prj_meet )total ORDER by createDate ASC

select total.* from ( SELECT allCon.* FROM ( SELECT conCount.* FROM ( -- 合同表 SELECT con.* FROM ( SELECT cc.contract_id as docId, cc.CREATION_DATE as createDate, '合同节点' as description, 'CON_CONTRACT' as docType, 'CON' as classType, 0 as processInstanceId, (SELECT scvb.MEANING FROM sys_code_value_b scvb WHERE scvb.CODE_ID=( SELECT scb.CODE_ID FROM sys_code_b scb WHERE scb.CODE='CON.CONTRACT_STATUS' ) AND scvb.VALUE=cc.contract_status) as currentStatus FROM con_contract cc WHERE
cc.contract_id=#{contractId}
ORDER BY createDate ) con UNION -- 合同签约 SELECT con_sign.* FROM ( SELECT ccs.contract_sign_id as docId, ccs.CREATION_DATE as createDate, '合同签约' as description, 'CON_CONTRACT_SIGN' as docType, 'CON' as classType, ccs.process_instance_id as processInstanceId, (SELECT scvb.MEANING FROM sys_code_value_b scvb WHERE scvb.CODE_ID=( SELECT scb.CODE_ID FROM sys_code_b scb WHERE scb.CODE='CON.CONTRACT_PROCESS_STATUS' ) AND scvb.VALUE=ccs.status) as currentStatus FROM con_contract_sign ccs WHERE
ccs.contract_id=#{contractId} and ccs.LAST_UPDATE_DATE = ( select max(t2.LAST_UPDATE_DATE) from con_contract_sign t2 where t2.contract_id = ccs.contract_id )
ORDER BY createDate ) con_sign UNION -- 合同付款申请 SELECT con_pay.* FROM ( SELECT cprl.payment_req_ln_id as docId, cprl.CREATION_DATE as createDate, '付款申请' as description, 'CON_CONTRACT_PAY' as docType, 'CON' as classType, 0 as processInstanceId, (SELECT scvb.MEANING FROM sys_code_value_b scvb WHERE scvb.CODE_ID=( SELECT scb.CODE_ID FROM sys_code_b scb WHERE scb.CODE='CON.CONTRACT_PROCESS_STATUS' ) AND scvb.VALUE=( SELECT cprh.payment_req_status FROM csh_payment_req_hd cprh WHERE cprh.payment_req_id = cprl.payment_req_id)) as currentStatus FROM csh_payment_req_ln cprl WHERE
cprl.source_doc_category='CON_CONTRACT' AND cprl.source_doc_id=#{contractId}
ORDER BY createDate ) con_pay UNION -- 合同起租申请 SELECT con_incept.* FROM ( SELECT cci.contract_incept_id as docId, cci.CREATION_DATE as createDate, '起租申请' as description, 'CON_CONTRACT_INCEPT' as docType, 'CON' as classType, cci.process_instance_id as processInstanceId, (SELECT scvb.MEANING FROM sys_code_value_b scvb WHERE scvb.CODE_ID=( SELECT scb.CODE_ID FROM sys_code_b scb WHERE scb.CODE='CON.CONTRACT_PROCESS_STATUS' ) AND scvb.VALUE=cci.status) as currentStatus FROM con_contract_incept cci WHERE
cci.contract_id=#{contractId} -- and cci.LAST_UPDATE_DATE = ( -- select max(t2.LAST_UPDATE_DATE) -- from con_contract_incept t2 -- where t2.contract_id = cci.contract_id -- )
ORDER BY createDate ) con_incept UNION -- 合同变更申请 SELECT con_change.* FROM ( SELECT cccr.change_req_id as docId, cccr.CREATION_DATE as createDate, ( select scvb.MEANING from sys_code_b scb,sys_code_value_b scvb where scb.code_id = scvb.code_id and scb.code = 'CON.CONTRACT_CHANGE_TYPE' and scvb.value = cccr.change_type ) description, 'CON_CONTRACT_CHANGE' as docType, 'CON' as classType, cccr.process_instance_id as processInstanceId, (SELECT scvb.MEANING FROM sys_code_value_b scvb WHERE scvb.CODE_ID=( SELECT scb.CODE_ID FROM sys_code_b scb WHERE scb.CODE='CON.CONTRACT_PROCESS_STATUS' ) AND scvb.VALUE=cccr.status) as currentStatus FROM con_contract_change_req cccr WHERE
cccr.contract_id=#{contractId}
ORDER BY createDate ) con_change UNION -- 合同撤销 SELECT con_cancel.* FROM ( SELECT ccc.contract_cancel_id as docId, ccc.CREATION_DATE as createDate, '合同取消' as description, 'CON_CONTRACT_CANCEL' as docType, 'CON' as classType, ccc.process_instance_id as processInstanceId, (SELECT scvb.MEANING FROM sys_code_value_b scvb WHERE scvb.CODE_ID=( SELECT scb.CODE_ID FROM sys_code_b scb WHERE scb.CODE='CON.CONTRACT_PROCESS_STATUS' ) AND scvb.VALUE=ccc.status) as currentStatus FROM con_contract_cancel ccc WHERE
ccc.contract_id=#{contractId}
ORDER BY createDate ) con_cancel
) conCount ORDER BY conCount.createDate DESC ) allCon )total ORDER by createDate ASC

SELECT cc.*, (select fe.name from fnd_employee fe where fe.employee_id=cc.employee_id)employeeIdName, (SELECT scvb.MEANING FROM sys_code_value_b scvb WHERE scvb.CODE_ID=( SELECT scb.CODE_ID FROM sys_code_b scb WHERE scb.CODE='CON.CONTRACT_STATUS' ) AND scvb.VALUE=cc.contract_status) as currentStatus, cc.sign_date -- ,(select max(ccs.process_instance_id) from con_contract_sign ccs where ccs.contract_id = cc.contract_id) process_instance_id, -- (select ccs.status from con_contract_sign ccs where ccs.contract_id = cc.contract_id limit 1) currentSignStatus, -- (SELECT scvb.MEANING FROM sys_code_value_b scvb WHERE scvb.CODE_ID=( -- SELECT scb.CODE_ID FROM sys_code_b scb WHERE scb.CODE='CON.CONTRACT_PROCESS_STATUS' -- ) AND scvb.VALUE=( -- select ccs.status from con_contract_sign ccs where ccs.contract_id = cc.contract_id limit 1 -- )) as currentSignStatusN FROM con_contract cc WHERE
cc.contract_id=#{contractId}
cc.project_id =#{projectId}
ORDER BY cc.CREATION_DATE

SELECT * FROM PRJ_PROJECT_APPROVAL ppa
   WHERE

       ppa.project_id=#{projectId}


       ppa.project_id in (
           SELECT cc.project_id FROM con_contract cc WHERE cc.contract_id=#{contractId}
       )

   ORDER BY ppa.CREATION_DATE
